```
FUNCTION_BLOCK FB
VAR_INPUT
    runRequest : BOOL;
    pressure : REAL;
    pressureValid : BOOL;
    fuelFlow : REAL;
    steamFlow : REAL;
    outletCmd : INT;
    outletFeedback : INT;
    resetBtn : BOOL;
END_VAR

VAR_OUTPUT
    tripLatched : BOOL;
    fuelPermit : BOOL;
    currentCauseMask : WORD;
    latchedCauseMask : WORD;
    diagnosticActive : BOOL;
END_VAR

VAR
    prevResetBtn : BOOL;
    stickCounter : INT;
    risingReset : BOOL;
    tripCond : BOOL;
    valveStuckCond : BOOL;
    bit1Flag : BOOL;
    bit2Flag : BOOL;
    overpressureCond : BOOL;
END_VAR

// Detect rising edge of reset button
risingReset := resetBtn AND NOT prevResetBtn;

// Determine overpressure condition
overpressureCond := runRequest AND pressureValid AND (pressure >= 4500.0);

// Determine valve stuck condition this cycle
valveStuckCond := overpressureCond AND (outletCmd >= 50) AND (outletFeedback <= 10);

// Update stick counter
IF valveStuckCond THEN
    stickCounter := stickCounter + 1;
ELSE
    stickCounter := 0;
END_IF

// Determine bit1 (valve stuck) based on counter >= 3
bit1Flag := (stickCounter >= 3);

// Determine bit2 (excess combustion) - only evaluated when overpressureCond true
bit2Flag := overpressureCond AND (fuelFlow >= 4.0) AND (steamFlow <= 10.0);

// Compute currentCauseMask
IF NOT runRequest THEN
    currentCauseMask := 0;
ELSIF NOT pressureValid THEN
    currentCauseMask := 1; // bit0
ELSE
    // pressureValid = true
    IF pressure < 4500.0 THEN
        currentCauseMask := 0;
    ELSE
        // Overpressure condition
        IF bit1Flag THEN
            currentCauseMask := 2;
        ELSE
            currentCauseMask := 0;
        END_IF

        IF bit2Flag THEN
            currentCauseMask := currentCauseMask OR 4;
        END_IF

        // If neither bit1 nor bit2, set bit3 (unidentified)
        IF (NOT bit1Flag) AND (NOT bit2Flag) THEN
            currentCauseMask := 8;
        END_IF
    END_IF;
END_IF;

// Determine trip condition
tripCond := runRequest AND (NOT pressureValid OR (pressure >= 4500.0));

// Update tripLatched
IF tripCond THEN
    tripLatched := TRUE;
ELSIF risingReset AND NOT runRequest AND pressureValid AND (pressure <= 4200.0) THEN
    tripLatched := FALSE;
END_IF;

// Compute fuelPermit
fuelPermit := runRequest AND NOT tripLatched;

// Compute diagnosticActive
diagnosticActive := (currentCauseMask <> 0);

// Update latchedCauseMask
IF tripLatched THEN
    latchedCauseMask := latchedCauseMask OR currentCauseMask;
ELSE
    latchedCauseMask := 0;
END_IF;

// Update previous reset button for next cycle
prevResetBtn := resetBtn;
END_FUNCTION_BLOCK
```

